CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own profile read" ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY "Own profile update" ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_signup_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name) VALUES (new.id, coalesce(new.raw_user_meta_data->>'display_name','')); RETURN new; END; $$;
CREATE TRIGGER create_signup_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_signup_profile();
INSERT INTO public.profiles(id,display_name) SELECT id,coalesce(raw_user_meta_data->>'display_name','') FROM auth.users ON CONFLICT DO NOTHING;
CREATE TABLE public.businesses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL UNIQUE, name text NOT NULL, industry text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', contact_email text NOT NULL DEFAULT '', contact_phone text NOT NULL DEFAULT '', operating_hours text NOT NULL DEFAULT '', currency text NOT NULL DEFAULT 'USD', language text NOT NULL DEFAULT 'English', notifications boolean NOT NULL DEFAULT true, products text NOT NULL DEFAULT '', faqs text NOT NULL DEFAULT '', delivery_policy text NOT NULL DEFAULT '', ai_instructions text NOT NULL DEFAULT '', whatsapp_phone_number_id text NOT NULL DEFAULT '', whatsapp_business_account_id text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.businesses TO authenticated; GRANT ALL ON public.businesses TO service_role;
ALTER TABLE public.businesses ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('owner','admin','agent')), UNIQUE(user_id,business_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own membership" ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_business_member(target uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE business_id=target AND user_id=auth.uid()); $$;
REVOKE ALL ON FUNCTION public.is_business_member(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_business_member(uuid) TO authenticated;
CREATE POLICY "Business members read" ON public.businesses FOR SELECT TO authenticated USING(public.is_business_member(id));
CREATE POLICY "Owners update business" ON public.businesses FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE FUNCTION public.prevent_owner_change() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF new.owner_id IS DISTINCT FROM old.owner_id OR new.id IS DISTINCT FROM old.id THEN RAISE EXCEPTION 'Business identity cannot be changed'; END IF; RETURN new; END; $$;
CREATE TRIGGER prevent_owner_change BEFORE UPDATE ON public.businesses FOR EACH ROW EXECUTE FUNCTION public.prevent_owner_change();
CREATE TABLE public.business_credentials (business_id uuid PRIMARY KEY REFERENCES public.businesses(id) ON DELETE CASCADE, encrypted_token text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.business_credentials TO service_role; REVOKE ALL ON public.business_credentials FROM anon,authenticated;
ALTER TABLE public.business_credentials ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.create_business(business_name text, business_industry text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF length(trim(business_name)) < 2 OR length(business_name)>120 THEN RAISE EXCEPTION 'Invalid business name'; END IF; SELECT id INTO bid FROM public.businesses WHERE owner_id=auth.uid(); IF bid IS NOT NULL THEN RETURN bid; END IF; INSERT INTO public.businesses(owner_id,name,industry) VALUES(auth.uid(),trim(business_name),business_industry) RETURNING id INTO bid; INSERT INTO public.user_roles(user_id,business_id,role) VALUES(auth.uid(),bid,'owner'); RETURN bid; END; $$;
REVOKE ALL ON FUNCTION public.create_business(text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_business(text,text) TO authenticated;
REVOKE ALL ON FUNCTION public.create_signup_profile() FROM PUBLIC;